from pathlib import Path
p = Path('/home/ubuntu/mesago-delivery/client/src/pages/Partners.tsx')
text = p.read_text()
text = text.replace('  const { data: catalog = [] } = trpc.catalog.list.useQuery({});', '  const { data: catalog = [] } = trpc.catalog.list.useQuery({});\n  const { data: liveOrders = [], refetch: refetchOrders } = trpc.order.feed.useQuery({ statuses: ["placed", "accepted", "ready"] }, { refetchInterval: 5000 });\n  const requestRider = trpc.order.requestRider.useMutation({ onSuccess: () => { toast.success("Solicitud enviada a riders cercanos"); refetchOrders(); } });')
needle = '<div className="mt-7 grid gap-4 md:grid-cols-2">'
insert = '''<div className="mt-7 rounded-2xl border border-[#e9dfd5] bg-[#fffaf3] p-4"><div className="mb-3 flex items-center justify-between"><div><p className="font-extrabold">Pedidos entrantes</p><p className="text-xs text-[#718076]">Se actualiza automáticamente cada 5 segundos.</p></div><span className="flex items-center gap-1.5 rounded-full bg-[#eaf2e5] px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wide text-[#315b3f]"><span className="h-1.5 w-1.5 rounded-full bg-[#56a362]" /> En vivo</span></div>{liveOrders.length ? <div className="space-y-2">{liveOrders.slice(0, 4).map((order) => <div key={order.id} className="flex flex-wrap items-center gap-3 rounded-xl bg-white p-3"><div className="min-w-0 flex-1"><p className="text-sm font-extrabold">{order.id} · {order.restaurant}</p><p className="truncate text-xs text-[#718076]">{order.address} · {order.total.toFixed(2).replace(".", ",")} €</p></div><span className="rounded-full bg-[#ffe9df] px-2 py-1 text-[10px] font-extrabold uppercase text-[#d95737]">{order.status === "placed" ? "Nuevo" : order.status === "ready" ? "Listo" : "Aceptado"}</span>{order.status !== "ready" && <button onClick={() => requestRider.mutate({ id: order.id })} className="rounded-full bg-[#315b3f] px-3 py-2 text-xs font-extrabold text-white">Solicitar rider</button>}</div>)}</div> : <div className="rounded-xl bg-white p-4 text-sm text-[#718076]">No hay pedidos pendientes en este momento.</div>}</div>\n        <div className="mt-7 grid gap-4 md:grid-cols-2">'''
text = text.replace(needle, insert, 1)
p.write_text(text)
